import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class JacksonAnnotationIntrospector_findInjectableValueId_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case: Annotation is null.
     * Coverage: if (ann == null) branch.
     */
    @Test
    public void testFindInjectableValueId_NoAnnotation() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        // Since _findAnnotation is protected, we rely on the fact that it returns null 
        // if the annotation is not present on the mock.
        // In a real Jackson environment, _findAnnotation searches the member's annotations.
        // We mock the behavior via a spy or by ensuring the mock returns nothing.
        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(null);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertNull(result);
    }

    /**
     * Test case: Annotation exists and has a non-empty value.
     * Coverage: returns id;
     */
    @Test
    public void testFindInjectableValueId_WithExplicitId() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("myCustomId");

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertEquals("myCustomId", result);
    }

    /**
     * Test case: Annotation has empty string value, and member is NOT an AnnotatedMethod (e.g., a Field).
     * Coverage: if (id.length() == 0) -> if (!(m instanceof AnnotatedMethod)) branch.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_Field() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(m.getRawType()).thenReturn(String.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertEquals(String.class.getName(), result);
    }

    /**
     * Test case: Annotation has empty string value, member is AnnotatedMethod with 0 parameters.
     * Coverage: if (am.getParameterCount() == 0) branch.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodNoParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(0);
        when(am.getRawType()).thenReturn(String.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(am, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(am);
        assertEquals(String.class.getName(), result);
    }

    /**
     * Test case: Annotation has empty string value, member is AnnotatedMethod with parameters.
     * Coverage: returns am.getRawParameterType(0).getName();
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodWithParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(1);
        when(am.getRawParameterType(0)).thenReturn(Integer.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(introspector);
        when(spyIntrospector._findAnnotation(am, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(am);
        assertEquals(Integer.class.getName(), result);
    }
}
